"""Admission gate: only architectures generated by the axiom system pass.

An architecture manifest (information_boltzmann/architectures/<name>.json) lists
every mechanism of the model. The gate admits the model only if all three layers pass:

1. Lineage. Every mechanism of kind "mechanism" or "structure" cites Lean theorems
   that exist in the current audit inventory and depend only on the standard axioms
   (propext, Classical.choice, Quot.sound). The inventory must match the current
   sources. Only kind "constant" (numbers that learning or evolution may tune) may
   cite nothing.
2. Execution. Every licensed mechanism names checks that run on the real
   implementation and confirm it computes what the theorem states.
3. Medium. The manifest names a Lean `Medium` instance whose `Axioms` proof is in
   the inventory.

Usage: python scripts/cgb_gate.py <name> [--json out.json] [--require-admitted]
"""

from __future__ import annotations

import argparse
import copy
import hashlib
import json
from pathlib import Path
import sys

import numpy as np

ROOT = Path(__file__).resolve().parents[1]
ARCH = ROOT / "information_boltzmann" / "architectures"
LEAN = ROOT / "lean" / "CGBAxioms"
INVENTORY = LEAN / ".lake" / "audit_inventory.json"
STANDARD = {"propext", "Classical.choice", "Quot.sound"}
sys.path.insert(0, str(ROOT / "information_boltzmann" / "core"))


def load_inventory():
    data = json.loads(INVENTORY.read_text(encoding="utf-8"))
    sources = sorted((LEAN / "CGBAxioms").rglob("*.lean")) + [LEAN / "CGBAxioms.lean"]
    current = {p.relative_to(LEAN).as_posix(): hashlib.sha256(p.read_bytes()).hexdigest() for p in sources}
    fresh = current == data.get("source_hashes")
    trusted = bool(data.get("proof_trust_passed")) and bool(data.get("module_coverage_passed"))
    return {d["name"]: d for d in data["declarations"]}, fresh, trusted


# ---------- executable checks on the real implementation ----------

class _Forced:
    """Stands in for the organism's random source so act() takes a chosen action."""

    def __init__(self, action):
        self.u = 0.0 if action == 1 else 1.0

    def random(self):
        return self.u


def _organism(hidden=16, seed=3):
    from cgb_lg1_forager import G15Organism
    m = G15Organism(hidden, seed=seed, eta=0.05, relax=1.0, diffuse=0.3, feedback=0.1, recur=2.0,
                    pg_eta=0.1, pg_trace=0.9)
    rng = np.random.default_rng(seed)
    m.Wp = rng.normal(0, 0.7, m.Wp.shape)
    m.p1 = rng.random(hidden).astype(np.float32)
    m.ate, m.n, m.bl = 1, 3, 0.4
    return m


def _policy(m):
    z = m.Wp @ m.features()
    pi = np.exp(z - z.max())
    return pi / pi.sum()


def _forced_update(m, action, intake):
    m = copy.deepcopy(m)
    m.ep[:] = 0.0
    m.prng = _Forced(action)
    w0 = m.Wp.copy()
    assert m.act() == action
    m.learning = False
    m.sense(65, intake, False)
    return m.Wp - w0


def check_softmax_readout():
    m = _organism()
    pi = _policy(m)
    m.prng = np.random.default_rng(0)
    counts = np.zeros(2)
    for _ in range(20000):
        counts[m.act()] += 1
    freq = counts / counts.sum()
    return abs(freq[1] - pi[1]) < 0.02, dict(softmax_switch=float(pi[1]), empirical_switch=float(freq[1]))


def check_g15_policy_gradient():
    m = _organism()
    R = {0: 1, 1: 0}
    x, pi = m.features(), _policy(m)
    expected = sum(pi[a] * _forced_update(m, a, R[a]) for a in (0, 1))
    J = sum(pi[a] * R[a] for a in (0, 1))
    theorem = m.pg_eta * np.outer([pi[b] * (R[b] - J) for b in (0, 1)], x)
    err = float(np.abs(expected - theorem).max())
    return err < 1e-9, dict(max_abs_error=err, baseline=m.bl)


def check_g15_outcome_blind_zero():
    m = _organism()
    pi = _policy(m)
    drift = sum(pi[a] * _forced_update(m, a, 1) for a in (0, 1))
    err = float(np.abs(drift).max())
    return err < 1e-9, dict(max_abs_drift=err)


def check_g14_delta_rule():
    from cgb_lg1 import LG1
    m = LG1(16, seed=5, eta=0.05, relax=1.0, diffuse=0.3, feedback=0.1)
    rng = np.random.default_rng(5)
    m.W1 = rng.normal(0, 0.3, m.W1.shape).astype(np.float32)
    m.p1 = rng.random(16).astype(np.float32)
    pi, p, w0, b = m.predict(), m.p1.copy(), m.W1.copy(), 101
    m.observe(b)
    e = -pi
    e[b] += 1.0
    err = float(np.abs((m.W1 - w0) - m.eta * np.outer(p - 0.5, e)).max())
    return err < 1e-5, dict(max_abs_error=err)


def check_miss_counter_distinguishes():
    m = _organism()
    m.ate, m.n = 0, 0
    seen = set()
    for _ in range(m.nmax + 1):
        seen.add(int(np.argmax(m.features()[:m.ns])))
        m.sense(65, 0, False)
    return len(seen) == m.nmax + 1, dict(distinct_states=len(seen), required=m.nmax + 1)


def check_interior_symmetric():
    m = _organism()
    err = float(np.abs(m.R - m.R.T).max())
    return err == 0.0, dict(max_asymmetry=err)


def check_score_trace_geometric():
    m = _organism()
    rng = np.random.default_rng(1)
    m.ep = rng.normal(0, 1, m.Wp.shape)
    before = m.ep.copy()
    m.prng = _Forced(1)
    x, pi = m.features(), _policy(m)
    m.act()
    score = -pi
    score[1] += 1.0
    err = float(np.abs(m.ep - (m.pg_lam * before + np.outer(score, x))).max())
    return err < 1e-12, dict(max_abs_error=err, decay=m.pg_lam)


def check_p2_symmetric_exchange():
    from cgb_lg1 import LG1
    m = LG1(16, seed=7, eta=0.05, relax=0.0, diffuse=0.3, feedback=0.1)
    rng = np.random.default_rng(7)
    m.p1 = rng.random(16).astype(np.float32)
    m.p2 = rng.random(16).astype(np.float32)
    p1, p2 = m.p1.astype(np.float64), m.p2.astype(np.float64)
    m.observe(66)
    tot = float(np.abs((m.p1 + m.p2) - (p1 + p2)).max())
    diff = float(np.abs((m.p1 - m.p2) - (1 - 2 * m.diffuse) * (p1 - p2)).max())
    return max(tot, diff) < 1e-5, dict(total_error=tot, difference_error=diff)


def check_grown_R_rule():
    from cgb_lg1_forager import G15Organism
    m = G15Organism(16, seed=4, eta=0.05, relax=1.0, diffuse=0.3, feedback=0.1, grown_R=True)
    rng = np.random.default_rng(4)
    for _ in range(50):
        m.prng = rng
        m.act()
        m.sense(int(rng.integers(32, 127)), int(rng.random() < 0.5), False)
    g = m.growth
    sym = float(np.abs(m.R - m.R.T).max())
    recip = float(np.abs(m.R - g.kappa / g.n_c * g.n).max())
    # the occupancy target is the G18c sigmoid of kappa * c - theta_i - theta_j
    field = g.kappa * g.c - (g.theta[:, None] + g.theta[None, :])
    occ = 1.0 / (1.0 + np.exp(-np.clip(field, -60, 60)))
    form = float(np.abs(g.target() - occ).max())
    ok = sym < 1e-6 and recip < 1e-5 and form < 1e-12 and float(np.abs(g.c - g.c.T).max()) < 1e-12
    return ok, dict(asymmetry=sym, reciprocity_error=recip, occupancy_form_error=form)


CHECKS = {k[len("check_"):]: v for k, v in list(globals().items()) if k.startswith("check_")}


# ---------- gate ----------

def gate(name):
    man = json.loads((ARCH / f"{name}.json").read_text(encoding="utf-8"))
    decls, fresh, trusted = load_inventory()
    lineage, execution, failures = [], [], []
    if not fresh:
        failures.append("Lean inventory is stale: rebuild and run lean/CGBAxioms/scripts/audit.py")
    if not trusted:
        failures.append("Lean audit trust/coverage did not pass")
    for mech in man["mechanisms"]:
        row = dict(id=mech["id"], kind=mech["kind"], theorems={})
        for t in mech.get("theorems", []):
            d = decls.get(t)
            row["theorems"][t] = ("missing" if d is None else
                                  "nonstandard axioms" if not set(d["axioms"]) <= STANDARD else "ok")
        licensed = bool(row["theorems"]) and all(v == "ok" for v in row["theorems"].values())
        if mech["kind"] == "constant":
            row["status"] = "constant (allowed)"
        elif licensed:
            row["status"] = "licensed"
        else:
            row["status"] = "UNLICENSED"
            failures.append(f"{mech['id']} ({mech['kind']}): no valid Lean theorem")
        lineage.append(row)
        if not licensed:
            continue
        if not mech.get("checks"):
            failures.append(f"{mech['id']}: licensed but no executable check on the implementation")
        for c in mech.get("checks", []):
            try:
                ok, info = CHECKS[c]() if c in CHECKS else (False, dict(error="unknown check"))
            except Exception as exc:  # a crashing check is a failing check
                ok, info = False, dict(error=repr(exc))
            execution.append(dict(mechanism=mech["id"], check=c, passed=bool(ok), **info))
            if not ok:
                failures.append(f"{mech['id']}: check {c} failed")
    med = man.get("lean_medium")
    if not med:
        failures.append("no Lean Medium instance with an Axioms proof")
    elif med not in decls:
        failures.append(f"Lean Medium instance {med} not in inventory")
    return dict(architecture=name, implementation=man.get("implementation"), inventory_fresh=fresh,
                lineage=lineage, execution=execution, lean_medium=med,
                admitted=not failures, failures=failures)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("name")
    ap.add_argument("--json")
    ap.add_argument("--require-admitted", action="store_true")
    a = ap.parse_args()
    r = gate(a.name)
    if a.json:
        Path(a.json).write_text(json.dumps(r, indent=1), encoding="utf-8")
    print(f"{r['architecture']}: {'ADMITTED' if r['admitted'] else 'NOT ADMITTED'}")
    for row in r["lineage"]:
        print(f"  [{row['status']}] {row['id']}")
    for e in r["execution"]:
        print(f"  check {e['check']}: {'pass' if e['passed'] else 'FAIL'}")
    for f in r["failures"]:
        print("  - " + f)
    return 1 if (a.require_admitted and not r["admitted"]) else 0


if __name__ == "__main__":
    raise SystemExit(main())
